import asyncio
from circuitbreaker import circuit

@circuit(failure_threshold=3, recovery_timeout=30)
async def resilient_call(fn, *args, **kwargs):
    return await fn(*args, **kwargs)

async def self_heal_monitor():
    while True:
        try:
            health = await check_internal_health()
            if not health['ok']:
                await restart_component(health['failed_component'])
                await event_bus.emit(f'garcar.{SYSTEM_ID}.self_heal.triggered', health)
        except Exception as e:
            pass
        await asyncio.sleep(30)

